import 'package:cloud_firestore/cloud_firestore.dart';import 'package:firebase_auth/firebase_auth.dart';import 'package:flutter/material.dart';import 'login_screen.dart';import '../home/home_screen.dart';import '../admin/admin_dashboard.dart';class AuthGate extends StatelessWidget{const AuthGate({super.key});@override Widget build(BuildContext c)=>StreamBuilder<User?>(stream:FirebaseAuth.instance.authStateChanges(),builder:(c,s){if(s.connectionState==ConnectionState.waiting)return const Scaffold(body:Center(child:CircularProgressIndicator()));if(!s.hasData)return const LoginScreen();return FutureBuilder<DocumentSnapshot<Map<String,dynamic>>>(future:FirebaseFirestore.instance.collection('users').doc(s.data!.uid).get(),builder:(c,d){if(!d.hasData)return const Scaffold(body:Center(child:CircularProgressIndicator()));return d.data!.data()?['role']=='admin'?const AdminDashboard():const HomeScreen();});});}